custom_css:
/*灰度日记-烤冷面大王*/
/*禁止商用禁止二传*/


/* ✨✨✨如果因为背景导致文字看不清楚，可以调整root气泡透明度部分*/

/*气泡透明度*/
:root {
  --透明度: 0 !important;/*0~1之间自己改*/
}

/*头像+自定义图片下的线*/
:root {
  --线的颜色: #BCA7EE;
  --线的透明度: 0.7;
}

/*思维链颜色*/
:root {
  --思维链颜色: #BCA7EE;
}

@import url("https://fontsapi.zeoseven.com/415/main/result.css");
@import url("https://fontsapi.zeoseven.com/293/main/result.css");

body {
    font-family: "WenYuan Serif SC VF";
    font-weight: normal;
}



/*✨1、顶栏*/
#top-settings-holder {
    background: #fff!important;   
    border-radius: 0 !important;
    box-shadow: none !important;
    filter: none !important;  
    height: 40px !important;
}
/* 删除顶栏阴影 */
#top-bar {
  box-shadow: none !important;
}

/*顶栏图标*/
#top-settings-holder .drawer-icon::before {
  font-size: 20px !important;
  color: #BCA7EE !important; 
  display: inline-block;
  vertical-align: middle;
}



/*✨2、底栏*/
#send_form {
    margin-bottom: 2px;
    width: 100%;
    background: rgba(255, 255, 255, 0.15) !important;
    background-repeat: no-repeat;
    background-size: cover;
    background-position: center center;
    border-radius: 0 !important;
    border: 1px solid rgba(255, 255, 255, 0) !important;
    padding: 8px;
}

/*底栏图标*/
#options_button::before,
#extensionsMenuButton::before,
#quick-reply-rocket-button i::before,
#send_but::before,
#mes_stop i::before {
  font-size: 20px !important;
  color: #BCA7EE !important;
}



/*byN老师*/
#form_sheld {
  position: absolute;
  bottom: 20px; /* 调整上下 */
}

#send_form {
  width: 92%; /* 调整宽度 */
  border-radius: 25px !important;

}

/* 最后一条消息与底栏间距 */
#chat {
  padding-bottom: 150px !important;
}

/* 输入长文本时底栏不挡正文by咩野 */
#form_sheld:has(#send_textarea:focus),
#form_sheld:has(#send_textarea:not(:placeholder-shown)) {
  position: static;
}


/* 输入框 */
#send_textarea {
    border-radius: 20 !important;
    clip-path: none !important;
    background-color: rgba(193, 172, 245, 0.15) !important;
    border: 0.5px solid rgba(0, 0, 0, 0.1) !important;
}

/* ===== by墨千尾老师，输入框提示文字自定义 ===== */
#nonQRFormItems {
    position: relative;
}
#send_textarea::placeholder {
    color: transparent !important;
    text-shadow: none !important; 
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
    content: "⊹ ♡┈┈┈ 𓏴⊹ ♡┈┈┈ ♡ ⊹𓏴 ┈┈┈♡ ⊹";/*🌷输入框自定义文字*/
    color: #BCA7EE !important;
    position: absolute; 
    left: 54%;
    top: 50%;
    transform: translate(-50%, -50%); 
    font-style: normal; 
    font-size: 0.5em; 
    pointer-events: none;
    z-index: 10;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: calc(100% - 30px);
}

/* --- byNini老师，默认隐藏 QR 按钮容器，并设置平滑过渡 --- */
.qr--buttons {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  transform: translateY(20px);
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.5s ease,
    transform 0.5s ease;
}

/* --- 输入框获得焦点时显示 QR 区域 --- */
#send_form:focus-within .qr--buttons {
  opacity: 1;
  visibility: visible;
  max-height: 120px;
  transform: translateY(0);
  pointer-events: auto;
}

/* --- 新增：修复空白弹窗，仅隐藏空白背景，不影响点击 --- */
#qr--bar {
  opacity: 0;
  visibility: hidden;
  max-height: 0;
  pointer-events: none;
  transition:
    opacity 0.3s ease-in-out,
    visibility 0.3s ease-in-out,
    max-height 0.3s ease;
}

/* --- 当输入框聚焦或激活时才显示 QR bar 内容 --- */
#send_form:focus-within #qr--bar,
.qr--buttons.active #qr--bar {
  opacity: 1;
  visibility: visible;
  max-height: 200px;
  pointer-events: auto;
}


/*分割线*/
hr {
    all: unset !important;
    display: block !important;
    visibility: visible !important;
    height: auto !important;
    text-align: center !important;
    margin: 10px 0 !important;
}

hr::after {
    content: ".⋅𓏴┊☆𓏵✩ ┊𓏴 ★ 𓏴┊ ✩𓏵̩̩͙☆ ┊𓏴‎⋅. "/*🌷自定义分割线*/!important;
    font-family: "LXGW WenKai Mono";
    font-weight: 300px;
    color: #BCA7EE !important;
    font-size: 15px !important;
}


/*菜单页分割线*/
div#extensionsMenu hr,
div.options-content hr {
  margin: 8px 0 !important;
}
div#extensionsMenu hr::after,
div.options-content hr::after {
  font-size: 6px !important;
  color: #BCA7EE !important;
}




/*✨3、头像+三元素+名字、时间戳*/
/* 彻底禁用头像点击放大 */
.mesAvatarWrapper,
.mesAvatarWrapper .avatar,
.mesAvatarWrapper .avatar * {
  pointer-events: none !important;
}

/*头像*/
.mes {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  gap: 0 !important;
  padding: 20px 10px !important;
}

.mes .mesAvatarWrapper {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 4px !important;
  width: auto !important;
  margin-bottom: 8px !important;
}

.mes .avatar img {
    /* 🌷头像图片大小⬇️ */
  width: 150px !important;  
  height: 150px !important;

  /*🌷头像显示区域⬇️*/
  object-position: 50% 20%;/*左右、上下，左右没什么用，主要调整上下*/


  transform: translateX(-140px) !important; /* 🌷头像左右移动 */
  border-radius: 0% !important; 
}



/* 豆包提供别动，头像彻底去白边 + 去阴影 */
.mes .avatar {
  background: transparent !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
}

.mes .avatar img {
  background: transparent !important;
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  margin: 0 !important;
  clip-path: none !important;
}




/* 三元素 */
.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay {
  display: inline-block !important;
  font-size: 0.95em !important;
  color: #BCA7EE !important;
  margin: 0 !important;
  padding: 0 !important;
  line-height: 1.2 !important;
  text-align: center !important;
  transform: translateX(-90px) !important; /* 🌷三元素左右移动 */
}

/*🌷🌷🌷三元素前后自定义文字*/
/* 楼层前面后面加字 */
.mesIDDisplay::before {
  content: "等";
}
.mesIDDisplay::after {
  content: "次钟楼敲响";
}

/* 计时器前面后面加字 */
.mes_timer::before {
  content: "借";
}
.mes_timer::after {
  content: "月光";
}

/* 字符前面后面加字 */
.tokenCounterDisplay::before {
  content: "在";
}
.tokenCounterDisplay::after {
  content: "相遇里只与你重逢";
}



/*名字单独占一行*/
.name_text {
  flex-basis: 60%;
  display: flex;
  justify-content: center;
  font-size: 16px !important; /* 这里改名字大小 */

  /* 🌷名字上下左右移动⬇️ */
  transform: translateY(0px) translateX(20px) !important; 
}


.name_text::before {
  content: "◎ ";
  margin-right: 4px;
}

/*时间戳*/
.mes .timestamp {
 /* 🌷时间戳上下左右移动⬇️ */
  transform: translateY(0px) translateX(20px) !important; 
}



/* 文本框与下一个头像框隔开 */
.mes {
  margin-bottom: 10em !important; 
  clear: both !important; 
}


/* by墨千尾老师，让消息框里的文字铺满消息框 */
.mes .mes_text {
    width: 100%;
    padding: 20px 0px 20px 3px;
    margin: 0px 0px 0px 0px;
    position: relative;
    z-index: 9999 !important;
}

/*来自12老师，拉进最后一条消息头像与名字距离*/
.mes .mesAvatarWrapper {
    padding: 0 !important;
}


/*头像+自定义图片下的线*/
.mes::before {
  content: "" !important;
  display: block !important;
  width: 100% !important;
  height: 1px !important;
  background: color-mix(in srgb, var(--线的颜色), transparent calc(100% * (1 - var(--线的透明度)))) !important;
  position: absolute;
  z-index: 1;
  pointer-events: none;

  /*🌷横线上下位置⬇️*/
  top: 275px;

}

/*🌷🌷🌷🌷🌷头像右侧自定义图片区🌷🌷🌷🌷🌷*/
.mes::after {
  content: '';
  position: absolute;
  z-index: 1;
  pointer-events: none;

  /*🌷自定义图片位置⬇️*/
  top: 20px;
  left: 210px;

   /*🌷自定义图片大小⬇️*/
  width: 150px;
  height: 250px;


  border-radius: 0%;
  background-image: url('https://i.postimg.cc/7Y87DTkq/IMG-6034.jpg');/*🌷自定义图片*/
  background-size: cover;
  background-position: center;  
}



/*面板背景*/
.drawer-content {
    background: linear-gradient(rgba(255,255,255,0.5), rgba(255,255,255,0.5)), url('https://i.postimg.cc/B6PLfJ7q/IMG-6035.jpg') center/cover fixed no-repeat;/*🌷自定义面板背景*/
}




/*✨4、思维链*/
.mes_reasoning {
    font-weight: 220; 
    line-height: 1.7; 
    text-align: justify; 
    --top-padding: 0rem;
    --bottom-padding: 1rem;
    --left-padding: 0.1rem;
    --right-padding: 0.1rem;
    padding: var(--top-padding) var(--right-padding) var(--bottom-padding) var(--left-padding);
}

/* 来自12老师，隐藏思维链背景 */
#chat .mes .mes_reasoning_header {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    border-radius: 0;
    backdrop-filter: none !important; 
    -webkit-backdrop-filter: none !important; 
    padding: 0 !important;
    margin-bottom: 0 !important;
    color: rgba(0, 0, 0, 0.7) !important;
    font-size: 1em !important;
    display: inline-flex !important;
    align-items: center !important;
    transition: none !important; 
}
/*来自hy老师，隐藏箭头 */
.mes_reasoning_arrow {
    display: none !important;
}

/*来自N老师*/
.mes_reasoning_header_title::before {
    content: "𖠸ֺּ𓏵𓈒ॱཾ⑅";/*🌷自定义思维链文字*/
    font-size: 15px;
    color: var(--思维链颜色) !important; 
    position: relative;
    margin-left:40px;

}

.mes_reasoning_header_title {
    font-size: 0;
}



/*✨5、三个点+小铅笔*/
/*来自蝶老师*/
.mes_button, .extraMesButtons>div {
  cursor: pointer;
  transition: all 0.2s ease-in-out;
  filter: drop-shadow(0 0 0px rgba(0,0,0,0)) !important;
  color: #BCA7EE !important;
  opacity: 1 !important;

}

/*⭕核心优化：移除阴影*/
input[type="range"] {
    filter: none; 
}



/*小铅笔展开后位置*/
div.mes_edit_buttons {
  transform: translateY(45px) !important;
  position: relative !important;
  z-index: 10 !important;
  width: 80% !important; 
  left: 10% !important;
}

/*🌷小铅笔+三个点上下*/
div.mes_buttons {
  margin-top: 40px !important;
}



/*✨6、杂项*/
/*——切页——*/
.swipe_left::before{
  content: '⊲' !important;
  color: rgba(193, 172, 245, 0.15) !important;
  font-size: 20px !important;
}
.swipe_right::before {
  content: '⊳' !important;
  color: rgba(193, 172, 245, 0.15) !important;
  font-size: 20px !important;
}
.swipe_left:hover, .swipe_right:hover {
  transform: scale(1.1);
  color: rgba(193, 172, 245, 0.15) !important;
}
.swipes-counter { 
  color: rgba(193, 172, 245, 0.15);
  opacity: 1 !important;
  transform: translateY(50px) !important;
}

.swipe_right, .swipe_left {
  opacity: 1 !important;
  background: none !important;
  background-image: none !important;
  background-repeat: no-repeat;
  background-position: center;
  transition: transform 0.2s ease;
  width: 40px;
  height: 40px;
  transform: translateY(55px) !important;
  display: flex;
  align-items: center;
  justify-content: center;
}



/*滑块图标*/
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    width: 10px !important;
    height: 10px !important;
    border-radius: 50% !important;
    box-shadow: none !important;
    cursor: ew-resize !important;
    opacity: 1 !important;
    filter: none !important;
    -webkit-filter: none !important;
    border: none !important;
    background: #9370DB !important; /* 淡紫色，可自行改色值 */
}


/* 去阴影 */
.fa-pencil-alt,
.fa-pencil,
.fa-ellipsis-h,
.fa-ellipsis,
.fa-pencil-alt:hover,
.fa-pencil:hover,
.fa-ellipsis-h:hover,
.fa-ellipsis:hover {
  box-shadow: none !important;
  text-shadow: none !important;
  filter: none !important;
  border: none !important;
  outline: none !important;
  background-color: transparent !important;
}
/* 去阴影，小眼睛、小星星 */
.menu_button, .fa-eye, .fa-ranking-star {
    text-shadow: none !important;
    box-shadow: none !important;
    filter: none !important; 
}

/*哈基米赞助去阴影别动！*/
/* 1. 彻底清除所有图标的文字阴影 */
.fa-solid, .fa-regular, .fa-brands, i {
    text-shadow: none !important;
    filter: none !important;
}

/* 2. 针对圆形按钮容器*/
.menu_button, .drawer-content i, .fa-button {
    box-shadow: none !importan;
    border: none !important;
}

/* 3. 针对列表图标容器 */
#show_main_menu, #show_extensions_menu {
    box-shadow: none !important;
    text-shadow: none !important;
}

/* 4. 强制取消所有可能导致阴影的滤镜 */
* {
    --box-shadow: none !important;
    --text-shadow: none !important;
}


/*===来自12老师，收藏区===*/
/* 收藏区左右滑动 */
#HotSwapWrapper {
  overflow: hidden;
}
#HotSwapWrapper > div {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
  height: calc(var(--avatar-base-height) + 10px);
}

body.big-avatars #HotSwapWrapper > div {
  height: calc(var(--avatar-base-height) * var(--big-avatar-height-factor) + 10px);
}
#HotSwapWrapper > div::-webkit-scrollbar {
  height: 5px; 
}
#HotSwapWrapper > div::-webkit-scrollbar-thumb {
  background-color: rgba(193, 172, 245, 0.15) !important; 
  border-radius: 5px; 
}
.character_select.is_fav .avatar {
  outline: 2px solid rgba(255, 255, 255, 0.8) !important;
}

/* 收藏角色边框  */
.character_select.is_fav .avatar {
    outline: 2px solid #C1ACF5 !important;
    box-shadow: 0 0 6px #C1ACF5, 0 0 12px #C1ACF5, 0 0 18px #C1ACF5 !important;
}

/* 收藏角色名字  */
.character_select.is_fav .ch_name {
    color: #222 !important;
    text-shadow: 0 0 6px #C1ACF5, 0 0 12px #C1ACF5, 0 0 24px #C1ACF5 !important;
}

/* by咩咩咩咩咩咩野老师，全局隐藏 Webkit 系浏览器的滚动条 */
::-webkit-scrollbar {
  display: none;
}

/* Firefox 全局滚动条样式 */
html {
  scrollbar-width: thin; /* auto | thin | none */

  scrollbar-color: #888 #f1f1f1; /* 滑块颜色 轨道颜色 */
}


/* --- 折叠面板按键  --- */
.inline-drawer-icon {
    -webkit-appearance: none;
    appearance: none;
    width: 25px !important; 
    height: 25px !important; 
    background: transparent !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    cursor: pointer;
    filter: none !important; 
    opacity: 1 !important; 
    color: #C1ACF5 !important;!important; 
    border: none !important; 
    box-shadow: none !important;
    font-size: 22px !important;
    font-weight: bold !important;
}

.inline-drawer-icon::before {
    content: "⌄" !important; /* 下箭头 */
    display: block !important;
    width: auto !important;
    height: auto !important;
    color: #C1ACF5!important;
    filter: none !important;
    opacity: 1 !important; 
    text-shadow: none !important;
}

.inline-drawer-icon:hover::before {
    transform: scale(1.2) !important;
}

/*by12老师*/
/* 删除消息时的勾选框样式 */
.mes.selected {
    background-color: #C1ACF5 /* 自行更改颜色 */!important; 
}

.mes.selected .mes_text {
    background-color: var(--chiikawa-cream) !important; /* 保持消息文本区域颜色 */
    color: var(--chiikawa-brown) !important; /* 保持文字颜色 */
}




/*✨8、提示词管理byserein老师 */
#rm_extensions_block .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    color: #C1ACF5 !important;
    background: rgba(198, 178, 246, 0.15)  !important;
    background-size: 100%;
    border-radius: 0px 0px 0px 0px;
    border: 1px solid #BCA7EE !important;
}


/* ===== 抽屉标题 hover 交互：悬停时文字变黑 ===== */
#rm_extensions_block .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    color: #C1ACF5 !important; /* 默认淡紫色文字 */
    background: rgba(198, 178, 246, 0.15) !important;
    border: 1px solid #BCA7EE !important;
    transition: all 0.2s ease; /* 加个平滑过渡，不会太生硬 */
}

/* 鼠标悬停时：文字变黑，背景加深一点 */
#rm_extensions_block .inline-drawer-toggle.inline-drawer-header:hover,
#user-settings-block h4:hover,
.standoutHeader:hover {
    color: #000000 !important; /* 文字纯黑 */
    background: rgba(198, 178, 246, 0.3) !important; /* 背景加深，让对比更明显 */
    border-color: #BCA7EE !important;
}


#completion_prompt_manager .completion_prompt_manager_prompt {
    border-radius: 0px !important;
    padding: 5px !important;
}
.completion_prompt_manager_prompt .fa-asterisk,
.completion_prompt_manager_prompt .fa-square-poll-horizontal,
.completion_prompt_manager_prompt .fa-syringe,
.completion_prompt_manager_prompt .fa-thumb-tack,
.fa-xs.fa-solid.fa-robot {
    color: #C1ACF5 !important;
}
.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
    color: #C1ACF5 !important;
}
#completion_prompt_manager .completion_prompt_manager_header_advanced span,
#completion_prompt_manager .completion_prompt_manager_header div,
.prompt_manager_prompt_controls span {
    filter: none !important;
    color: #C1ACF5 !important;
}
.inline-drawer-header .inline-drawer-icon {
    color: #C1ACF5 !important;
    transform: scale(0.8);
}

/* 预设底板  */
#completion_prompt_manager, 
#completion_prompt_manager_list {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt {
    background: #fff !important;
    border: 1px solid #BCA7EE !important; /* 细边 */
    border-radius: 10px !important;    /* 圆角 */
    color: #C1ACF5 !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt:hover {
    background: rgba(198, 178, 246, 0.25) !important;
    border-color: #BCA7EE !important;
    color: #C6B2F6 !important;
    transform: translateY(-2px); 
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.08) !important;
    cursor: pointer;
}



/* ===== ✨9、通用 UI 组件  ===== */
.menu_button, .right_menu_button {
    background-color: #fff!important;
    color: #C1ACF5 !important;
    border: 1px solid #BCA7EE !important;
    border-radius: 1px !important;
    transition: background-color 0.3s ease, transform 0.2s ease !important;
}

.menu_button:hover, .right_menu_button:hover {
    color: #BCA7EE;
    background-color: rgba(193, 172, 245, 0.25) !important;
    transform: translateY(-2px);
}

.avatar-container.interactable.selected {
    background: #fff !important;
