/* ✨11、最近聊天列表容器 */
div.recentChat {
  background: rgba(255, 255, 255, 0.5)  !important; /* 纯白底 */
  border: 1px solid #BAA1F6 !important;
  border-radius: 0px !important;
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.1) !important;
  overflow: hidden !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 单条聊天项（hover 效果） */
.recent-chat-item {
  background: transparent !important;
  transition: background 0.2s !important;
}
.recent-chat-item:hover {
  background: #f5f5f5 !important; /* 浅灰悬浮 */
}


/*----菜单+扩展打开页面----*/
div#extensionsMenu,
div.options-content {
    background: url('https://i.postimg.cc/B6PLfJ7q/IMG-6035.jpg') !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    background-size: cover !important;
    border: #BAA1F6 !important;
    border-radius: 12px !important;  
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}



/*变量区透明度对应部分*/
/*聊天气泡*/
.mes_text {
  position: relative !important;
  background: rgb(255 255 255 / var(--透明度)) !important;
  border: 1px solid rgba(255, 255, 255, 0) !important;
  border-radius: 0 !important;
  left: -2px !important; /*🌷气泡左右*/
  top:5px;/*🌷气泡上下*/
}

.mesIDDisplay,
.mes_timer,
.tokenCounterDisplay,
.name_text,
.mes .timestamp {
  background: rgb(255 255 255 / var(--透明度)) !important;
  border-radius: 0px !important;
  padding: 0px 0px !important;
  display: inline-block !important;
}
